def string(**kw): return {'type':'string', **kw}
def enum(*xs): return {'enum':list(xs)}
def array(items, **kw): return {'type':'array','items':items, **kw}
def obj(props, required=None, extra=False, **kw):
    return {'type':'object','properties':props,'required':list(props) if required is None else required,'additionalProperties':extra, **kw}
def ref(file): return {'$ref': BASE + file + '.schema.json'}
def common(name): return {'$ref':BASE+'common.schema.json#/$defs/'+name}
def nullable(s): return {'anyOf':[s,{'type':'null'}]}
def strs(**kw): return array(string(minLength=1), **kw)
def ids(**kw): return array(common('id'), uniqueItems=True, **kw)
def write_schema(name, body):
    data={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':BASE+name+'.schema.json','title':'AI Friendly Audit — '+name, **body}
    (SCHEMAS/(name+'.schema.json')).write_text(json.dumps(data,indent=2)+'\n')

